-- Atomic coaching-text-only update. Explicit before/after guards prevent lost edits.
-- No video, name, code, category, active status, default dosage or programme changes.
DO $coaching$
DECLARE
  changes jsonb := $changes$[{"code":"ACC01","name":"Wall March","video_id":"bBfLvmrHDkc","video_url":"https://www.youtube.com/shorts/bBfLvmrHDkc","before":{"description":"Face a firm wall with your hands at shoulder height. Lean from your ankles. Lift one knee, set your foot down under your hip and switch legs.","purpose":"Practise acceleration posture and controlled single-leg support.","coaching_cues":"Cue: Step down under your hip. Avoid: Bending at the waist. Stop if it hurts or you lose control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Face a stable wall with hands at shoulder height. Lean from your ankles in a straight line; lift one knee, place the foot back under your hip and alternate as assigned. Follow the assigned effort or time; stop if pain or loss of control develops.","purpose":"Practise acceleration posture and controlled single-leg support.","coaching_cues":"Cue: Long body. Hips forward. Foot under hip. Avoid: Folding at the waist, arching the lower back or reaching the foot ahead.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"ACC02","name":"Wall Switch","video_id":"aIRTnxFAZNE","video_url":"https://www.youtube.com/shorts/aIRTnxFAZNE","before":{"description":"Lean into a firm wall with your body in a straight line and one knee up. Switch legs as shown and put the new support foot down under your hip.","purpose":"Practise coordinated leg exchanges while holding an acceleration position.","coaching_cues":"Cue: Switch under your hips. Avoid: Letting your hips bounce up and down. Stop if it hurts or you lose control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Set a straight-body lean against a stable wall. Exchange the raised and supporting legs as demonstrated, landing the supporting foot under the hip; reset if posture changes. Follow the assigned effort or time; stop if pain or loss of control develops.","purpose":"Practise coordinated leg exchanges while holding an acceleration position.","coaching_cues":"Cue: Push the wall. Switch under hips. Keep your shape. Avoid: Bouncing the hips, collapsing through the shoulders or trading control for speed.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"ACC03","name":"Falling Start","video_id":"IdFSYpV9z20","video_url":"https://www.youtube.com/shorts/IdFSYpV9z20","before":{"description":"On a clear lane with room to slow down, stand tall and lean forward from your ankles. When you need to step, push into your run. Slow down after the finish.","purpose":"Practise projecting the body into the first acceleration steps.","coaching_cues":"Cue: Lean as one piece. Avoid: Bending at the waist or leaning past your control. Stop if it hurts or you lose control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"On a clear, non-slip lane, stand tall with feet under hips. Lean forward from the ankles until a step is needed, then push into the assigned run and slow down beyond the finish. Follow the assigned effort or time; stop if pain or loss of control develops.","purpose":"Practise projecting the body into the first acceleration steps.","coaching_cues":"Cue: Lean as one. Push away. Rise gradually. Avoid: Bending at the waist, falling beyond control or stopping abruptly at the finish.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"ACC04","name":"Two-Point Start","video_id":"sD1iGWZ_4Qs","video_url":"https://www.youtube.com/shorts/sD1iGWZ_4Qs","before":{"description":"Put one foot in front of the other on a clear lane. Put your weight on the front foot and push into your first steps. Rise as you build speed.","purpose":"Practise a balanced standing start and purposeful first steps.","coaching_cues":"Cue: Push the ground back. Avoid: Reaching too far on the first step. Stop if it hurts or you lose control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Use a staggered stance on a clear lane, with the front foot loaded and arms ready. Push into the first steps and let the body rise as speed builds. Follow the assigned effort or time; stop if pain or loss of control develops.","purpose":"Practise a balanced standing start and purposeful first steps.","coaching_cues":"Cue: Push back. Drive arms. Rise with speed. Avoid: Reaching for a long first step, jumping upward or forcing the head down.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"ACC05","name":"10–30m Acceleration","video_id":"","video_url":"","before":{"description":"Use the start, distance and effort your coach assigned. Build speed on a clear lane. Leave room to ease down after the finish.","purpose":"Build speed through progressive acceleration over the assigned distance.","coaching_cues":"Cue: Build speed with each step. Avoid: Reaching too far ahead with your feet. Stop if it hurts or you lose control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Use the start Coach Du assigns and check the lane and run-out are clear. Accelerate over the prescribed 10–30 m at the assigned effort, then ease down gradually. Follow the assigned effort or time; stop if pain or loss of control develops.","purpose":"Build speed through progressive acceleration over the assigned distance.","coaching_cues":"Cue: Push with intent. Build each step. Run through the finish. Avoid: Overstriding, forcing a low posture or adding distance or effort beyond the programme.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"ACT01","name":"Glute Bridge","video_id":"nD1CM76NlVs","video_url":"https://www.youtube.com/shorts/nD1CM76NlVs","before":{"description":"Lie on your back with both feet flat and your knees bent. Push through your feet to lift your hips, then lower slowly.","purpose":"Develop controlled hip extension using the glute muscles.","coaching_cues":"Cue: Squeeze your glutes as your hips rise. Avoid: Arching your lower back to lift higher. Stop if it hurts or you lose control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Lie on your back on a mat with knees bent and feet flat. Press through the feet to lift the hips in line with the trunk, then lower smoothly. Use only the assigned load and volume; stop if pain or loss of control develops.","purpose":"Develop controlled hip extension using the glute muscles.","coaching_cues":"Cue: Ribs settled. Squeeze glutes. Lower slowly. Avoid: Pushing so high that the lower back arches, or letting the knees drift inward.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"ACT02","name":"Single-Leg Glute Bridge","video_id":"zZD--pmOBLM","video_url":"https://www.youtube.com/shorts/zZD--pmOBLM","before":{"description":"Lie on your back with one foot flat. Hold the other leg in the position your coach assigns. Push through the foot on the floor to lift your hips, then lower slowly.","purpose":"Develop hip extension and pelvic control on one supporting leg.","coaching_cues":"Cue: Keep both hips level. Avoid: One hip dropping or your lower back arching. Stop if it hurts or you lose control. Stop if you feel a cramp or pain.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Lie on your back with one foot planted and the other leg held as demonstrated. Lift and lower the hips while keeping both sides of the pelvis level; use the assigned range. Use only the assigned load and volume; stop if pain or loss of control develops.","purpose":"Develop hip extension and pelvic control on one supporting leg.","coaching_cues":"Cue: Level hips. Push through the planted foot. Control down. Avoid: Twisting the pelvis, arching the lower back or continuing through cramp or pain.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"ACT03","name":"Side-Lying Hip Abduction","video_id":"c3eH-sc8uBM","video_url":"https://www.youtube.com/shorts/c3eH-sc8uBM","before":{"description":"Lie on your side with one hip above the other. Keep your top leg straight, lift it a little and lower it slowly.","purpose":"Develop controlled strength at the side of the hip.","coaching_cues":"Cue: Keep your top hip stacked. Avoid: Rolling backward to lift higher. Stop if it hurts or you lose control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Lie on your side with the pelvis stacked and the top leg long. Lift that leg a small distance from the hip, then lower slowly without rolling the trunk. Use only the assigned load and volume; stop if pain or loss of control develops.","purpose":"Develop controlled strength at the side of the hip.","coaching_cues":"Cue: Stack hips. Reach long. Lower slowly. Avoid: Rolling backward, turning the toes upward to gain height or lifting beyond control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"ACT04","name":"Clamshell","video_id":"SRLwCVGL53E","video_url":"https://www.youtube.com/shorts/SRLwCVGL53E","before":{"description":"Lie on your side with your knees bent and feet together. Lift the top knee a little, then lower it slowly.","purpose":"Practise hip rotation while keeping the pelvis stable.","coaching_cues":"Cue: Keep your feet touching. Avoid: Rolling your top hip backward. Stop if it hurts or you lose control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Lie on your side with hips and knees bent, feet together. Open the top knee only as far as you can without rolling backward, then close slowly. Use only the assigned load and volume; stop if pain or loss of control develops.","purpose":"Practise hip rotation while keeping the pelvis stable.","coaching_cues":"Cue: Feet together. Hips stacked. Open from the hip. Avoid: Twisting the lower back, rolling the pelvis or forcing a large range.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"ACT05","name":"Fire Hydrant","video_id":"s73ByyYa1l4","video_url":"https://www.youtube.com/shorts/s73ByyYa1l4","before":{"description":"Start on your hands and knees. Keep one knee bent as you lift it out to the side. Lower it slowly.","purpose":"Develop hip control while maintaining a stable trunk.","coaching_cues":"Cue: Keep your hips facing the floor. Avoid: Turning your whole body to lift the knee higher. Stop if it hurts or you lose control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Start on hands and knees on a mat. With the knee bent, lift one thigh out to the side within a comfortable range and return slowly. Use only the assigned load and volume; stop if pain or loss of control develops.","purpose":"Develop hip control while maintaining a stable trunk.","coaching_cues":"Cue: Hands under shoulders. Hips level. Move from the hip. Avoid: Leaning away, arching the back or rotating the whole pelvis.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"ACT06","name":"Lateral Band Walk","video_id":"vAUZlEFjM9U","video_url":"https://www.youtube.com/shorts/vAUZlEFjM9U","before":{"description":"Put the band in the position your coach assigns. Bend your knees slightly, step sideways and bring your other foot in slowly.","purpose":"Develop lateral hip control while stepping against a band.","coaching_cues":"Cue: Keep a little tension in the band. Avoid: Dragging your second foot or letting the band go slack. Stop if it hurts or you lose control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Place a resistance band where shown in the demo and take a small athletic stance. Step sideways, then bring the trailing foot in under control while keeping band tension. Use only the assigned load and volume; stop if pain or loss of control develops.","purpose":"Develop lateral hip control while stepping against a band.","coaching_cues":"Cue: Small steps. Knees follow toes. Control the trailing foot. Avoid: Dragging the feet, snapping them together or using a band too strong to control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"ACT07","name":"Monster Walk","video_id":"K-RCj59qZ5Y","video_url":"https://www.youtube.com/shorts/K-RCj59qZ5Y","before":{"description":"Put the band in the position your coach assigns. Bend your knees slightly and take short diagonal steps in the assigned direction.","purpose":"Develop hip control during resisted diagonal stepping.","coaching_cues":"Cue: Small steps, steady hips. Avoid: Taking steps so wide that you sway. Stop if it hurts or you lose control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Use the band position and walking direction demonstrated. Take short diagonal steps from a comfortable athletic stance, maintaining controlled band tension. Use only the assigned load and volume; stop if pain or loss of control develops.","purpose":"Develop hip control during resisted diagonal stepping.","coaching_cues":"Cue: Steady hips. Small steps. Keep tension. Avoid: Swaying the trunk, letting knees collapse inward or overstretching the band.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"ACT08","name":"Single-Leg Bridge Hold","video_id":"JkdDIbfxMTQ","video_url":"https://www.youtube.com/shorts/JkdDIbfxMTQ","before":{"description":"Lie on your back with one foot flat. Hold the other leg as assigned. Lift your hips, keep breathing during the hold and lower slowly.","purpose":"Develop single-leg hip extension control during a timed hold.","coaching_cues":"Cue: Keep both hips level. Avoid: Letting one hip drop during the hold. Stop if it hurts or you lose control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Lie on your back, plant one foot and hold the other leg as shown. Lift to a level-hip bridge and hold for the assigned seconds while breathing; lower to finish. Use only the assigned load and volume; stop if pain or loss of control develops.","purpose":"Develop single-leg hip extension control during a timed hold.","coaching_cues":"Cue: Hips level. Ribs settled. Breathe steadily. Avoid: Counting repetitions instead of hold time, arching the back or holding after the hips drop.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"ACT09","name":"Table Position — 6-Movement Activation Series","video_id":"i7Kdkh2eSqE","video_url":"https://www.youtube.com/shorts/i7Kdkh2eSqE","before":{"description":"Ask Coach Du to confirm the movement sequence before you start. Use the order and positions your coach gives you.","purpose":"Prepare controlled activation in the demonstrated table-position series.","coaching_cues":"Cue: Keep your body steady as you change position. Avoid: Guessing the order or rushing between positions.","admin_notes":"Import batch exercise-video-expansion-20. Exact mapping supplied and release authorized by Coach Du. Playback and movement verification pending; do not treat this entry as independently verified. Coaching sequence, setup, equipment and dosage require review; no default prescription supplied. Preserve as one series; demonstrated movement order has not been verified.\nCoaching audit 2026-11-15: sequence-pending-coach-verification; general-cues-only; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Sequence not yet verified. Watch the full demonstration first. Ask Coach Du to confirm the movement sequence and starting positions before your first session; use only the assigned variations in the confirmed order. Keep transitions controlled and use the sets, repetitions or time on your training sheet.","purpose":"Prepare controlled activation in the demonstrated table-position series.","coaching_cues":"Cue: Steady support. Control transitions. Breathe. Avoid: Letting the shoulders collapse, rushing transitions or adding movements not assigned.","admin_notes":"Import batch exercise-video-expansion-20. Exact mapping supplied and release authorized by Coach Du. Playback and movement verification pending; do not treat this entry as independently verified. Coaching sequence, setup, equipment and dosage require review; no default prescription supplied. Preserve as one series; demonstrated movement order has not been verified.\nCoaching audit 2026-11-15: sequence-pending-coach-verification; general-cues-only; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"ACT10","name":"Seated Leg Raise Series","video_id":"licUqHf0kuw","video_url":"https://www.youtube.com/shorts/licUqHf0kuw","before":{"description":"Ask Coach Du to confirm the movement sequence before you start. Use the order and positions your coach gives you.","purpose":"Practise controlled seated leg movement with a steady trunk.","coaching_cues":"Cue: Lift and lower each leg slowly. Avoid: Guessing the order or rushing between positions.","admin_notes":"Import batch exercise-video-expansion-20. Exact mapping supplied and release authorized by Coach Du. Playback and movement verification pending; do not treat this entry as independently verified. Coaching sequence, setup, equipment and dosage require review; no default prescription supplied. Preserve as one series; demonstrated movement order has not been verified.\nCoaching audit 2026-11-15: sequence-pending-coach-verification; general-cues-only; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Sequence not yet verified. Watch the full demonstration first. Ask Coach Du to confirm the movement sequence and starting positions before your first session; use only the assigned variations in the confirmed order. Keep transitions controlled and use the sets, repetitions or time on your training sheet.","purpose":"Practise controlled seated leg movement with a steady trunk.","coaching_cues":"Cue: Sit tall. Move smoothly. Use a small range. Avoid: Throwing the legs, rocking backward to gain height or forcing hip range.","admin_notes":"Import batch exercise-video-expansion-20. Exact mapping supplied and release authorized by Coach Du. Playback and movement verification pending; do not treat this entry as independently verified. Coaching sequence, setup, equipment and dosage require review; no default prescription supplied. Preserve as one series; demonstrated movement order has not been verified.\nCoaching audit 2026-11-15: sequence-pending-coach-verification; general-cues-only; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"ACT11","name":"Superman Activation Series","video_id":"nDrQyHNwtRg","video_url":"https://www.youtube.com/shorts/nDrQyHNwtRg","before":{"description":"Ask Coach Du to confirm the movement sequence before you start. Use the order and positions your coach gives you.","purpose":"Practise controlled back-body activation in the demonstrated series.","coaching_cues":"Cue: Lift only as far as you can control. Avoid: Guessing the order or rushing between positions.","admin_notes":"Import batch exercise-video-expansion-20. Exact mapping supplied and release authorized by Coach Du. Playback and movement verification pending; do not treat this entry as independently verified. Coaching sequence, setup, equipment and dosage require review; no default prescription supplied. Preserve as one series; demonstrated movement order has not been verified.\nCoaching audit 2026-11-15: sequence-pending-coach-verification; general-cues-only; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Sequence not yet verified. Watch the full demonstration first. Ask Coach Du to confirm the movement sequence and starting positions before your first session; use only the assigned variations in the confirmed order. Keep transitions controlled and use the sets, repetitions or time on your training sheet.","purpose":"Practise controlled back-body activation in the demonstrated series.","coaching_cues":"Cue: Length before height. Easy breathing. Small controlled lifts. Avoid: Throwing limbs upward, straining the neck or forcing the lower back into an arch.","admin_notes":"Import batch exercise-video-expansion-20. Exact mapping supplied and release authorized by Coach Du. Playback and movement verification pending; do not treat this entry as independently verified. Coaching sequence, setup, equipment and dosage require review; no default prescription supplied. Preserve as one series; demonstrated movement order has not been verified.\nCoaching audit 2026-11-15: sequence-pending-coach-verification; general-cues-only; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"ACT12","name":"Glute Bridge Activation Series","video_id":"TYSVGbdo-lI","video_url":"https://www.youtube.com/shorts/TYSVGbdo-lI","before":{"description":"Ask Coach Du to confirm the movement sequence before you start. Use the order and positions your coach gives you.","purpose":"Practise controlled hip extension through the demonstrated bridge variations.","coaching_cues":"Cue: Keep your hips steady. Avoid: Guessing the order or rushing between positions.","admin_notes":"Import batch exercise-video-expansion-20. Exact mapping supplied and release authorized by Coach Du. Playback and movement verification pending; do not treat this entry as independently verified. Coaching sequence, setup, equipment and dosage require review; no default prescription supplied. Preserve as one series; demonstrated movement order has not been verified.\nCoaching audit 2026-11-15: sequence-pending-coach-verification; general-cues-only; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Sequence not yet verified. Watch the full demonstration first. Ask Coach Du to confirm the movement sequence and starting positions before your first session; use only the assigned variations in the confirmed order. Keep transitions controlled and use the sets, repetitions or time on your training sheet.","purpose":"Practise controlled hip extension through the demonstrated bridge variations.","coaching_cues":"Cue: Level hips. Ribs settled. Control each change. Avoid: Arching the lower back, rushing changes or treating every variation as extra assigned volume.","admin_notes":"Import batch exercise-video-expansion-20. Exact mapping supplied and release authorized by Coach Du. Playback and movement verification pending; do not treat this entry as independently verified. Coaching sequence, setup, equipment and dosage require review; no default prescription supplied. Preserve as one series; demonstrated movement order has not been verified.\nCoaching audit 2026-11-15: sequence-pending-coach-verification; general-cues-only; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"ANK01","name":"Calf Raise","video_id":"C3BmRILCdK8","video_url":"https://www.youtube.com/shorts/C3BmRILCdK8","before":{"description":"Stand tall and hold a firm support if needed. Rise onto the balls of your feet, then lower slowly. Use the one-leg or two-leg version you were assigned.","purpose":"Develop controlled calf strength through the assigned ankle range.","coaching_cues":"Cue: Rise straight up. Avoid: Rolling onto the outer edge of your foot. Stop if it hurts or you lose control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Stand with feet stable and use light hand support if needed. Rise through the balls of the feet and lower smoothly; use the one- or two-leg version prescribed. Use only the assigned load and volume; stop if pain or loss of control develops.","purpose":"Develop controlled calf strength through the assigned ankle range.","coaching_cues":"Cue: Rise tall. Keep ankles aligned. Control down. Avoid: Rolling onto the outside of the foot, bouncing or adding load before balance is steady.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"ANK02","name":"Bent-Knee Soleus Hold","video_id":"OAedc9Bl7rc","video_url":"https://www.youtube.com/shorts/OAedc9Bl7rc","before":{"description":"Hold a firm support if needed. Bend the knee slightly, lift the heel and keep the knee bent for the assigned time. Keep breathing.","purpose":"Develop calf capacity with the knee bent during a timed hold.","coaching_cues":"Cue: Keep the knee bent. Avoid: Straightening the knee as you get tired. Stop if it hurts or you lose control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Use stable hand support if needed. Keep the knee comfortably bent, raise the heel to the demonstrated position and hold for the prescribed seconds while breathing. Use only the assigned load and volume; stop if pain or loss of control develops.","purpose":"Develop calf capacity with the knee bent during a timed hold.","coaching_cues":"Cue: Knee stays bent. Heel steady. Foot aligned. Avoid: Straightening the knee, rolling the ankle outward or forcing a painful heel height.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"ANK03","name":"Calf ISO Hold","video_id":"IcitpPYKq2c","video_url":"https://www.youtube.com/shorts/IcitpPYKq2c","before":{"description":"Use the one-leg or two-leg position you were assigned. Rise onto the balls of your feet, hold for the assigned time, then lower slowly.","purpose":"Develop calf strength and ankle control during a timed hold.","coaching_cues":"Cue: Keep your heel at the same height. Avoid: Letting the heel drop during the hold. Stop if it hurts or you lose control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Stand with light support if needed and rise onto the balls of the feet. Hold the assigned one- or two-leg position for the prescribed seconds, then lower under control. Use only the assigned load and volume; stop if pain or loss of control develops.","purpose":"Develop calf strength and ankle control during a timed hold.","coaching_cues":"Cue: Stand tall. Heel steady. Keep breathing. Avoid: Bouncing, rolling the ankle or staying up after control is lost.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"ANK04","name":"Tibialis Raise","video_id":"4bidZUlkXV4","video_url":"https://www.youtube.com/shorts/4bidZUlkXV4","before":{"description":"Set up with a firm support as your coach shows you. Keep your heels down. Lift the front of your feet toward your shins, then lower slowly.","purpose":"Develop control of the muscles that lift the front of the foot.","coaching_cues":"Cue: Heels down, toes up. Avoid: Rocking your body back to lift your feet. Stop if it hurts or you lose control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Keep heels grounded in the supported position shown. Lift the toes and forefeet toward the shins, then lower smoothly without shifting the whole body. Use only the assigned load and volume; stop if pain or loss of control develops.","purpose":"Develop control of the muscles that lift the front of the foot.","coaching_cues":"Cue: Heels down. Toes up. Control the return. Avoid: Rocking backward and forward, lifting the heels or forcing ankle range.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"CORE01","name":"Dead Bug","video_id":"wJbZ9qqVZ2Q","video_url":"https://www.youtube.com/shorts/wJbZ9qqVZ2Q","before":{"description":"Lie on your back with your knees bent and arms above your chest. Reach one arm and the opposite leg away. Bring them back and switch sides.","purpose":"Practise trunk control while the opposite arm and leg move.","coaching_cues":"Cue: Keep your lower back steady. Avoid: Reaching so far that your back arches. Stop if it hurts or you lose control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Lie on a mat with arms above the chest and hips and knees bent. Reach the opposite arm and leg away only as far as the lower back stays controlled; return and alternate as assigned. Follow the assigned effort or time; stop if pain or loss of control develops.","purpose":"Practise trunk control while the opposite arm and leg move.","coaching_cues":"Cue: Ribs settled. Reach slowly. Breathe out. Avoid: Arching the lower back, rushing or reaching farther than you can control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"CORE02","name":"Front Plank","video_id":"cQ7fXKV7LlQ","video_url":"https://www.youtube.com/shorts/cQ7fXKV7LlQ","before":{"description":"Put your elbows under your shoulders. Use your knees or toes as assigned. Hold your body in one line and keep breathing.","purpose":"Develop trunk stability while maintaining a straight-body hold.","coaching_cues":"Cue: Keep your body in one line. Avoid: Letting your hips sag. Stop if it hurts or you lose control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Place forearms on a mat with elbows under shoulders and use the prescribed knee or toe support. Hold the body in one line for the assigned time while breathing. Follow the assigned effort or time; stop if pain or loss of control develops.","purpose":"Develop trunk stability while maintaining a straight-body hold.","coaching_cues":"Cue: Long body. Gentle brace. Keep breathing. Avoid: Sagging or hiking the hips, straining the neck or holding beyond good alignment.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"CORE03","name":"Side Plank","video_id":"HtGt0ISXRcE","video_url":"https://www.youtube.com/shorts/HtGt0ISXRcE","before":{"description":"Lie on your side with your elbow under your shoulder. Use your knees or feet as assigned, then lift your hips and hold while breathing.","purpose":"Develop lateral trunk and hip stability.","coaching_cues":"Cue: Lift your hips and stay steady. Avoid: Letting the top hip roll forward. Stop if it hurts or you lose control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Lie on your side with the elbow under the shoulder. Lift into the prescribed knee- or foot-supported side plank and hold a straight line for the assigned time. Follow the assigned effort or time; stop if pain or loss of control develops.","purpose":"Develop lateral trunk and hip stability.","coaching_cues":"Cue: Push the floor away. Lift hips. Breathe. Avoid: Collapsing into the shoulder, rotating the chest or holding after the hips drop.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"CORE04","name":"Bird Dog","video_id":"zPEiaA3TIl4","video_url":"https://www.youtube.com/shorts/zPEiaA3TIl4","before":{"description":"Start on hands and knees. Reach one arm forward and the opposite leg back. Return slowly and switch sides.","purpose":"Practise trunk stability during opposite arm and leg movement.","coaching_cues":"Cue: Keep both hips facing the floor. Avoid: Twisting your hips to reach farther. Stop if it hurts or you lose control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Start on hands and knees, hands under shoulders and knees under hips. Reach the opposite arm and leg long, return slowly and alternate as assigned. Follow the assigned effort or time; stop if pain or loss of control develops.","purpose":"Practise trunk stability during opposite arm and leg movement.","coaching_cues":"Cue: Reach long. Level hips. Keep the back quiet. Avoid: Lifting limbs so high the back arches, twisting the pelvis or shifting weight sharply.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"CORE05","name":"Plank Shoulder Tap","video_id":"-jpIJVsQaFo","video_url":"https://www.youtube.com/shorts/-jpIJVsQaFo","before":{"description":"Start in the push-up position you were assigned. Tap the opposite shoulder with one hand, put it back down and switch sides.","purpose":"Develop trunk control while briefly supporting on one arm.","coaching_cues":"Cue: Keep your hips still. Avoid: Rocking from side to side. Stop if it hurts or you lose control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Start in the prescribed push-up position on a mat, feet wide enough for balance. Lift one hand to tap the opposite shoulder and replace it slowly before switching. Follow the assigned effort or time; stop if pain or loss of control develops.","purpose":"Develop trunk control while briefly supporting on one arm.","coaching_cues":"Cue: Press the floor. Quiet hips. Slow tap. Avoid: Rocking side to side, dropping the hips or rushing the hand change.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"CORE06","name":"Hollow Hold","video_id":"FoEa8jNHFJA","video_url":"https://www.youtube.com/shorts/FoEa8jNHFJA","before":{"description":"Lie on your back and use the arm and leg position your coach assigns. Hold while you can keep your lower back steady and breathe normally.","purpose":"Develop trunk control while the arms and legs create a longer lever.","coaching_cues":"Cue: Keep your lower back steady. Avoid: Letting your back arch as your legs reach out. Stop if it hurts or you lose control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Lie on a mat and set the arm and leg position demonstrated. Lift or extend only as far as the lower back stays controlled; shorten the position if needed and hold for the assigned time. Follow the assigned effort or time; stop if pain or loss of control develops.","purpose":"Develop trunk control while the arms and legs create a longer lever.","coaching_cues":"Cue: Ribs down. Reach long. Keep breathing. Avoid: Arching the back, pulling the neck forward or using a longer lever than you can hold.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"CORE07","name":"Bear Hold","video_id":"aLwndUO5Mvc","video_url":"https://www.youtube.com/shorts/aLwndUO5Mvc","before":{"description":"Start on hands and knees with your toes tucked under. Lift your knees just off the floor. Stay there and keep breathing.","purpose":"Develop trunk and shoulder control in a low hovering position.","coaching_cues":"Cue: Float your knees just off the floor. Avoid: Lifting your hips so high that your knees move away from your hands. Stop if it hurts or you lose control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Start on hands and knees with toes tucked. Lift the knees just clear of the mat and hold for the assigned seconds while keeping the back steady. Follow the assigned effort or time; stop if pain or loss of control develops.","purpose":"Develop trunk and shoulder control in a low hovering position.","coaching_cues":"Cue: Knees low. Push the floor. Breathe. Avoid: Lifting the hips high, rounding or sagging the back, or holding your breath.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"CORE08","name":"Bear Shoulder Tap","video_id":"DTUL7sb_Ceo","video_url":"https://www.youtube.com/shorts/DTUL7sb_Ceo","before":{"description":"Start with your hands down and knees just off the floor. Tap the opposite shoulder with one hand, put it back and switch sides.","purpose":"Develop trunk control while changing hand support in a bear position.","coaching_cues":"Cue: Keep your hips still. Avoid: Rocking your hips with each tap. Stop if it hurts or you lose control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Start in a low bear hold on a mat. Tap the opposite shoulder with one hand, replace it and alternate only while the hips remain controlled. Follow the assigned effort or time; stop if pain or loss of control develops.","purpose":"Develop trunk control while changing hand support in a bear position.","coaching_cues":"Cue: Knees low. Slow hands. Quiet hips. Avoid: Rocking side to side, letting the knees drop suddenly or rushing beyond control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"CORE09","name":"Side Plank + Leg Lift","video_id":"qC7HjKu7uUA","video_url":"https://www.youtube.com/shorts/qC7HjKu7uUA","before":{"description":"Set up in the side plank you were assigned, with your elbow under your shoulder. Lift the top leg a little, then lower it slowly.","purpose":"Develop lateral trunk stability while controlling the top leg.","coaching_cues":"Cue: Keep your hips up as you lift. Avoid: Dropping your hips when the top leg moves. Stop if it hurts or you lose control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Set the prescribed side-plank support with the elbow under the shoulder. Lift the top leg a small distance and lower smoothly while keeping the hips raised. Follow the assigned effort or time; stop if pain or loss of control develops.","purpose":"Develop lateral trunk stability while controlling the top leg.","coaching_cues":"Cue: Long body. Hips stacked. Small leg lift. Avoid: Rolling the pelvis, dropping the supporting hip or lifting the leg at the expense of balance.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"CORE10","name":"Dead Bug Heel Tap","video_id":"v8u-DWDX6K4","video_url":"https://www.youtube.com/shorts/v8u-DWDX6K4","before":{"description":"Lie on your back with your knees bent and feet off the floor. Lower one heel to tap the floor lightly. Bring it back and switch sides.","purpose":"Practise trunk control during alternating heel reaches.","coaching_cues":"Cue: Tap softly and keep your back steady. Avoid: Arching your back to reach the floor. Stop if it hurts or you lose control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Lie on a mat with hips and knees bent as shown. Lower one heel to lightly touch the floor, return and alternate while the ribs and lower back stay controlled. Follow the assigned effort or time; stop if pain or loss of control develops.","purpose":"Practise trunk control during alternating heel reaches.","coaching_cues":"Cue: Move slowly. Ribs settled. Light heel touch. Avoid: Arching the back, dropping the leg or increasing range when control is lost.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"CORE11","name":"Plank Knee Drive","video_id":"bJtHsgKpyd0","video_url":"https://www.youtube.com/shorts/bJtHsgKpyd0","before":{"description":"Start in a push-up position with hands under shoulders. Bring one knee toward your chest, put the foot back and switch sides.","purpose":"Develop trunk stability during a controlled knee drive.","coaching_cues":"Cue: Keep your hips steady. Avoid: Letting your hips bounce with each step. Stop if it hurts or you lose control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"description":"Start in a push-up position with hands under shoulders. Draw one knee toward the chest in a comfortable range, return the foot and alternate as assigned. Follow the assigned effort or time; stop if pain or loss of control develops.","purpose":"Develop trunk stability during a controlled knee drive.","coaching_cues":"Cue: Press the floor. Quiet hips. Control the knee. Avoid: Sagging the back, twisting the pelvis or turning the drill into an unassigned fast run.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."}},{"code":"CORE12","name":"Bear Series — Opposite Toe Touch","video_id":"Tpp9h6tXNY8","video_url":"https://www.youtube.com/shorts/Tpp9h6tXNY8","before":{"description":"Ask Coach Du to confirm the movement sequence before you start. Use the order and positions your coach gives you.","purpose":"Practise coordination and trunk control in the demonstrated bear series.","coaching_cues":"Cue: Keep your hips steady when you reach. Avoid: Guessing the order or rushing between positions.","admin_notes":"Import batch exercise-video-expansion-20. Exact mapping supplied and release authorized by Coach Du. Playback and movement verification pending; do not treat this entry as independently v